function createGroundPatternTexture() {
  const canvas = document.createElement("canvas"); canvas.width = canvas.height = 64;
  const context = canvas.getContext("2d"); context.fillStyle = "#ffffff"; context.fillRect(0, 0, 64, 64);
  context.strokeStyle = "rgba(25,35,28,.16)"; context.lineWidth = 1;
  for (let offset = -64; offset < 128; offset += 16) { context.beginPath(); context.moveTo(offset, 0); context.lineTo(offset + 64, 64); context.stroke(); }
  context.fillStyle = "rgba(20,30,24,.14)";
  for (const [x, y] of [[8, 11], [28, 20], [51, 8], [18, 45], [43, 52], [59, 35]]) context.fillRect(x, y, 2, 2);
  const texture = new THREE.CanvasTexture(canvas); texture.wrapS = texture.wrapT = THREE.RepeatWrapping; texture.colorSpace = THREE.SRGBColorSpace; return texture;
}
