      { label: "Body fat", value: percent(composition.fatPercent), colour: composition.critical ? "#ff6767" : "#d8b958" },
      { label: "Water", value: percent(animal.hydration), colour: animal.hydration < 25 ? "#ff6767" : "#61c9ef" }
