      const active = Boolean(animal.alive && animal.predation?.targetKind === "prey" && animal.predation.targetId);
      if (active && !previous.active) { session.metrics.huntsInitiated += 1; if ((animal.stomach || 0) >= 55 && !carcassFamilyUrgency(animal)) session.metrics.satiatedHuntViolations += 1; }
