    if (start === previousStart && end === previousEnd) return;
    previousStart = start; previousEnd = end; windowRoot.replaceChildren(); windowRoot.style.transform = `translateY(${start * rowHeight}px)`;
    for (let index = start; index < end; index += 1) appendRow(windowRoot, entries[index]);
