  if (ui.embodimentSpecies) { const selected = ui.embodimentSpecies.value; ui.embodimentSpecies.innerHTML = `<option value="">Random valid species</option>${speciesForRole(role, species).map(s => `<option value="${s.id}">${s.label}</option>`).join("")}`; if ([...ui.embodimentSpecies.options].some(o => o.value === selected)) ui.embodimentSpecies.value = selected; }
  const summaries = { creative: "All cameras, both Laboratories, complete information and organism-only god tools.", easy: "All cameras and both Laboratories; unknown terrain is shaded.", standard: "All cameras and Mini Laboratory; unknown terrain is shaded.", challenging: "No total view; unknown terrain is black.", hard: "Close camera only; Mini Laboratory remains.", "very-hard": "Close camera only; Laboratory disabled.", extreme: "Role-only random organism, reduced HUD and close third-person.", "insane-immersion": "Embodied cameras and natural visual evidence only.", "impossible-immersion": "Autonomous first-person; influence needs and satisfiers only." };
