    investigate: "investigate a bonded animal's death",
    "avoid-site": "avoid a remembered death site",
    "track-killer": "track evidence from a bonded animal's death",
    "confront-killer": "defend against a confirmed killer",
    "rally-retaliation": "rally allies against a confirmed killer",
    "guard-body": "guard a bonded animal's body",
    "attend-body": "remain with a bonded animal's body",
