    const groupsById = new Map();
    for (const a of sim.animals) if (a.alive && a.groupId) { const group = groupsById.get(a.groupId) || { kind: a.speciesId, count: 0, x: 0, z: 0, goal: a.groupGoal || "travelling" }; group.count += 1; group.x += a.x; group.z += a.z; groupsById.set(a.groupId, group); }
    const metaGroupIds = new Set((sim.largeOrganizations || []).flatMap((organization) => organization.groupIds));
    const metaIndividualIds = new Set((sim.largeOrganizations || []).flatMap((organization) => organization.individualIds || []));
    for (const organization of sim.largeOrganizations || []) {
      const colour = organization.speciesIds.length > 1 ? "#9fe09b" : species[organization.speciesIds[0]]?.diet === "meat" ? "#bd6cff" : "#f1c84a";
      const sprite = new THREE.Sprite(mapNamedGroupMaterial(organization.name || organization.type, organization.count, colour));
      sprite.position.set(organization.centroid.x, terrainHeight(organization.centroid.x, organization.centroid.z) + 4.2, organization.centroid.z); sprite.scale.set(15.5, 4.85, 1); groups.overlays.add(sprite);
      sprite.userData.id = `organization:${organization.id}`; sprite.userData.populationMarkerKind = "organization"; pickables.set(sprite.userData.id, sprite);
    }
    for (const [groupId, group] of groupsById) if (group.count >= 2 && !metaGroupIds.has(groupId)) {
      const hunter = group.kind === "hunter", colour = hunter ? "#bd6cff" : "#f1c84a";
      const material = mapCountMaterial(group.kind, group.count, colour);
      const sprite = new THREE.Sprite(material), x = group.x / group.count, z = group.z / group.count;
      sprite.position.set(x, terrainHeight(x, z) + 3.4, z);
      sprite.scale.set(4.4, 4.4, 1);
      sprite.userData.id = `group:${groupId}`; sprite.userData.populationMarkerKind = "group"; pickables.set(sprite.userData.id, sprite); groups.overlays.add(sprite);
    }
    // Ungrouped organisms are collapsed into neutral local totals. Group members
