  const organizedIndividualIds = new Set(showOrganizations ? (sim.largeOrganizations || []).flatMap((organization) => organization.individualIds || []) : []);
  if (showOrganizations) for (const organization of sim.largeOrganizations || []) {
    const colour = organization.speciesIds.length > 1 ? "#9fe09b" : species[organization.speciesIds[0]]?.diet === "meat" ? "#bd6cff" : "#f1c84a";
      const sprite = new THREE.Sprite(mapNamedGroupMaterial(organization.name || organization.type, organization.count, colour));
      sprite.position.set(organization.centroid.x, terrainHeight(organization.centroid.x, organization.centroid.z) + 4.2, organization.centroid.z); sprite.scale.set(18, 5.6, 1); groups.overlays.add(sprite);
      sprite.userData.id = `organization:${organization.id}`; sprite.userData.populationMarkerKind = "organization"; pickables.set(sprite.userData.id, sprite);
  }
  const buckets = new Map(), span = Math.max(48, Math.ceil(WORLD / 3));
  for (const a of sim.animals) if (a.alive && !organizedGroupIds.has(a.groupId) && !organizedIndividualIds.has(a.id)) {
    const bx = Math.floor((a.x + HALF) / span), bz = Math.floor((a.z + HALF) / span), id = `${bx}:${bz}`;
    const b = buckets.get(id) || { count: 0, x: 0, z: 0 };
    b.count += 1; b.x += a.x; b.z += a.z; buckets.set(id, b);
  }
