  const socialEdges = records.map((record) => line(centre, malePositions.get(record.maleId), record.alignment >= .65 ? "social-edge positive" : record.alignment < .35 ? "social-edge negative" : "social-edge", record.alignment)).join("") + records.flatMap((record) => (record.sources || []).filter((id) => sourcePositions.has(id)).map((id) => line(sourcePositions.get(id), malePositions.get(record.maleId), "social-edge reported", .45))).join("");
