  const sources = sourceIds.map((id) => node(id, sourcePositions.get(id), "reporter", "reporter")).join("");
  const children = offspring.map((child) => node(child.id, childPositions.get(child.id), "offspring", "offspring")).join("");
  const grandchildNodes = grandchildren.map((entry) => node(entry.animal.id, grandchildPositions.get(entry.animal.id), "grandchild", "grandchild")).join("");
  const empty = records.length ? "" : `<text class="social-network-empty" x="290" y="${socialHeight / 2}">No mate observations or shared reports yet</text>`;
  const divider = offspring.length ? `<line class="social-network-divider" x1="18" y1="${socialHeight}" x2="502" y2="${socialHeight}"/><text class="social-network-section" x="18" y="${socialHeight + 18}">Descendants</text>` : "";
  return `<strong>Female social and family network</strong><div class="social-network-wrap"><svg class="social-network" viewBox="0 0 ${width} ${height}" role="img" aria-label="Social and descendant network for ${escapeHtml(female.id)}">${socialEdges}${kinEdges}${divider}${node(female.id, centre, "selected-female", "selected")}${males}${sources}${children}${grandchildNodes}${empty}</svg><div class="social-network-legend"><span class="female-key">Selected female</span><span class="male-key">Remembered male</span><span class="report-key">Reporting female</span><span class="offspring-key">Offspring</span><span class="grandchild-key">Grandchild</span></div></div>`;
