      for (const organization of capabilities && capabilities.id !== "creative" ? [] : sim.largeOrganizations || []) { const x = (organization.centroid.x + HALF) / WORLD * size, z = (organization.centroid.z + HALF) / WORLD * size; c.strokeStyle = "#7de6d0"; c.lineWidth = 2; c.beginPath(); c.arc(x, z, Math.min(10, 4 + Math.sqrt(organization.count)), 0, Math.PI * 2); c.stroke(); c.fillStyle = "#d9fff6"; c.font = "bold 8px system-ui"; c.textAlign = "center"; c.fillText("META", x, z - 7); }
